  let result = value;
  for (const part of parts) {
    if ((typeof result !== "object" || result === null) && typeof result !== "function") {
      return MISSING;
    }
    if (!Object.prototype.hasOwnProperty.call(result, part)) return MISSING;
    result = (result as Record<string, unknown>)[part];
