    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "\"": "&quot;",
    "'": "&#39;",
  })[character]!);
}

function renderNodes(nodes: Node[], context: Context, root: unknown): string {
  let output = "";
  for (const node of nodes) {
    if (node.kind === "text") {
      output += node.value;
    } else if (node.kind === "value") {
      const text = scalar(resolve(node.path, context, root), node.path, node.location);
      output += node.escaped ? escapeHtml(text) : text;
    } else {
      const value = resolve(node.path, context, root);
      if (node.block === "if") {
        output += renderNodes(isTruthy(value) ? node.truthy : node.falsy, context, root);
      } else if (Array.isArray(value) && value.length > 0) {
        for (let index = 0; index < value.length; index++) {
          output += renderNodes(node.truthy, { value: value[index], index, parent: context }, root);
        }
      } else {
        output += renderNodes(node.falsy, context, root);
      }
    }
  }
  return output;
}

/** Render a Mini Template string with the supplied data. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { value: data }, data);
}
import { render } from "./engine";

async function main(): Promise<void> {
  const [templatePath, dataPath, extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  process.stdout.write(render(template, data));
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`mini-template: ${message}\n`);
  process.exitCode = 1;
});
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine";

describe("interpolation", () => {
  test("escapes HTML and supports raw values and missing paths", () => {
    expect(render("{{value}}|{{{value}}}|{{missing}}", { value: `&<>\"'` }))
      .toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'|");
  });

  test("rejects non-scalar interpolation", () => {
    expect(() => render("x {{user}}", { user: { name: "Ada" } }))
      .toThrow("Value 'user' cannot be rendered as scalar text at line 1, column 3");
  });
});

describe("blocks", () => {
  test("implements the specified truthiness", () => {
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    for (const value of ["0", 1, true, {}, [0]]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
    }
  });

  test("iterates nested arrays with local paths, root fallback, and indices", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each this.items}}{{@index}}={{this}};{{else}}empty{{/each}}]{{/each}}";
    expect(render(template, {
      title: "root",
      groups: [{ name: "A", items: ["x", "y"] }, { name: "B", items: [] }],
    })).toBe("[A/root:0=x;1=y;][B/root:empty]");
  });

  test("uses each else for missing, non-array, and empty values", () => {
    expect(render("{{#each xs}}x{{else}}none{{/each}}", { xs: [] })).toBe("none");
    expect(render("{{#each xs}}x{{else}}none{{/each}}", { xs: "no" })).toBe("none");
  });
});

test("comments disappear and whitespace is exact", () => {
  expect(render(" a \n{{! ignore me }}\n b ", {})).toBe(" a \n\n b ");
});

describe("syntax diagnostics", () => {
  test.each([
    ["{{#wat x}}", "Unknown block 'wat' at line 1, column 1"],
    ["a\n{{else}}", "'else' outside a block at line 2, column 1"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate 'else' at line 1, column 18"],
    ["{{#if x}}{{/each}}", "Mismatched closing block 'each'; expected 'if' at line 1, column 10"],
    ["{{/if}}", "Unexpected closing block 'if' at line 1, column 1"],
    ["{{#each xs}}", "Unclosed 'each' block at line 1, column 1"],
    ["hello {{name", "Unclosed tag at line 1, column 7"],
  ])("reports %s", (template, message) => {
    expect(() => render(template, { x: true })).toThrow(message);
  });
});
# Mini Template

A dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{user.name}}!", { user: { name: "Ada" } });
```

Run it from the command line (rendered text is the only stdout output):

```sh
bun run src/cli.ts template.txt data.json
```

## Syntax

- `{{path.to.value}}` inserts HTML-escaped text.
- `{{{path.to.value}}}` inserts unescaped text.
- `{{#if path}}...{{else}}...{{/if}}` conditionally renders a branch.
- `{{#each path}}...{{else}}...{{/each}}` iterates arrays. Use `{{this}}` and `{{@index}}`; item properties are resolved before falling back to root data.
- `{{! comment }}` renders nothing.

Missing values render as empty strings. Objects, functions, and other non-scalar interpolation values throw an error. Block syntax errors include their line and column.

```sh
bun test
bun run typecheck
```

