    ["a\n{{else}}", "'else' outside a block at line 2, column 1"],
    ["{{#if x}}{{else}}{{else}}{{/if}}", "Duplicate 'else' at line 1, column 18"],
    ["{{#if x}}{{/each}}", "Mismatched closing block 'each'; expected 'if' at line 1, column 10"],
